const noticias = pm.response.json().content;

pm.test("Responde 200", () => pm.response.to.have.status(200));

pm.test("Devuelve al menos 3 noticias", () => {
    pm.expect(noticias.length).to.be.at.least(3);
});

pm.test("Cada noticia tiene título y resumen", () => {
    noticias.forEach(n => {
        pm.expect(n.titulo).to.be.a("string").and.not.empty;
        pm.expect(n.resumen).to.be.a("string").and.not.empty;
    });
});

pm.test("Ordenadas de la más reciente a la más antigua", () => {
    const f = noticias.map(n => new Date(n.fechaPublicacion).getTime());
    pm.expect(f).to.eql([...f].sort((a, b) => b - a));
});

const eventos = pm.response.json();

pm.test("Responde 200", () => pm.response.to.have.status(200));

pm.test("Hay al menos 1 evento cargado", () => {
    pm.expect(eventos.length).to.be.at.least(1);
});

pm.test("Cada evento tiene fecha, horario y disciplina", () => {
    eventos.forEach(e => {
        pm.expect(e.fechaEvento).to.be.a("string").and.not.empty;
        pm.expect(e.cronograma).to.be.a("string").and.not.empty;
        pm.expect(e.disciplina).to.be.a("string").and.not.empty;
    });
});

pm.test("Ordenados cronológicamente", () => {
    const f = eventos.map(e => new Date(e.fechaEvento + "T" + e.cronograma).getTime());
    pm.expect(f).to.eql([...f].sort((a, b) => a - b));
});
